export const SEPARATOR = '%%%'

/**
 * Splits the input on newlines, drops the empty tail a trailing newline
 * leaves, and cuts the lines into documents at every `%%%` line.
 *
 * @returns {string[][]} one array of lines per document.
 */
export function parseDocuments(input) {
  const lines = input.split('\n')
  if (input.endsWith('\n')) lines.pop()

  const documents = [[]]
  for (const line of lines) {
    if (line === SEPARATOR) documents.push([])
    else documents[documents.length - 1].push(line)
  }
  return documents
}
"}

