{"file_path":"src/merge.js","content":"/** The three-way merge itself: changes, regions, resolutions. */

import { diffLines } from './diff.js'

const MINE = 'mine'
const THEIRS = 'theirs'

/**
 * The changes of both sides in one list, ordered by where they start in the
 * base, mine's changes first when two start at the same place.
 */
function gatherChanges(mine, base, theirs) {
  const changes = []
  for (const change of diffLines(base, mine)) changes.push({ ...change, side: MINE })
  for (const change of diffLines(base, theirs)) changes.push({ ...change, side: THEIRS })
  changes.sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side === b.side) return 0
    return a.side === MINE ? -1 : 1
  })
  return changes
}

/** Groups the changes into the base stretches the merge has to resolve. */
function groupChanges(changes) {
  const groups = []
  let at = 0
  while (at < changes.length) {
    const first = changes[at]
    const group = { baseStart: first.baseStart, baseEnd: first.baseEnd, changes: [first] }
    at += 1
    while (at < changes.length && changes[at].baseStart <= group.baseEnd) {
      group.baseEnd = Math.max(group.baseEnd, changes[at].baseEnd)
      group.changes.push(changes[at])
      at += 1
    }
    groups.push(group)
  }
  return groups
}

/** One side's lines for a group, stretched out to the whole group. */
function sideLines(group, document, base, side) {
  const own = group.changes.filter(change => change.side === side)
  if (own.length === 0) return base.slice(group.baseStart, group.baseEnd)

  let first = own[0]
  let last = own[0]
  for (const change of own) {
    if (change.baseStart < first.baseStart) first = change
    if (change.baseEnd > last.baseEnd) last = change
  }
  const start = first.sideStart - (first.baseStart - group.baseStart)
  const end = last.sideEnd + (group.baseEnd - last.baseEnd)
  return document.slice(start, end)
}

const sameLines = (a, b) => a.length === b.length && a.every((line, index) => line === b[index])

/**
 * The whole merge as a list of regions, in order. A stable region carries the
 * base lines it keeps; a resolved region carries the lines it resolves to; a
 * conflict carries the three runs.
 */
export function mergeRegions(mine, base, theirs) {
  const regions = []
  let baseAt = 0
  const stable = end => {
    if (end > baseAt) regions.push({ kind: 'stable', lines: base.slice(baseAt, end) })
  }

  for (const group of groupChanges(gatherChanges(mine, base, theirs))) {
    stable(group.baseStart)
    baseAt = group.baseEnd

    const ours = sideLines(group, mine, base, MINE)
    const theirsLines = sideLines(group, theirs, base, THEIRS)
    const baseRun = base.slice(group.baseStart, group.baseEnd)
    const touchedByMine = group.changes.some(change => change.side === MINE)
    const touchedByTheirs = group.changes.some(change => change.side === THEIRS)

    if (sameLines(ours, theirsLines)) {
      let kind = 'both'
      if (!touchedByTheirs) kind = MINE
      else if (!touchedByMine) kind = THEIRS
      regions.push({ kind, lines: ours })
    } else if (sameLines(ours, baseRun)) {
      regions.push({ kind: THEIRS, lines: theirsLines })
    } else if (sameLines(theirsLines, baseRun)) {
      regions.push({ kind: MINE, lines: ours })
    } else {
      regions.push({ kind: 'conflict', mine: ours, base: baseRun, theirs: theirsLines })
    }
  }
  stable(base.length)
  return regions
}
"}

